Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).

Abbreviation SEGS := Plain.M.loaded_segments.

Definition SMV      : Z := 0x664c8.
Definition MVA1E    : Z := 0x6850c.
Definition MVA1R    : Z := 0x6652c.
Definition MVA3E    : Z := 0x6860c.
Definition X_PC     : Z := 0x665f8.
Definition MVA3R    : Z := 0x66608.
Definition V1_PC    : Z := 0x66608.
Definition Z1_PC    : Z := 0x66620.
Definition V2_PC    : Z := 0x66650.
Definition Z2_PC    : Z := 0x66668.
Definition V3_PC    : Z := 0x66698.
