Definition EPI_PC   : Z := 0x666e0.
Definition RET_PC   : Z := 0x666f8.
Definition DELSZ    : Z := 0x6db74.
Definition DELETE   : Z := 0x6db70.

Definition STOPS : list Z := [MVA1E; MVA1R; MVA3E; DELSZ; V1_PC; V2_PC; V3_PC; EPI_PC; RET_PC].

Set Warnings "-notation-for-abbreviation".

Set Implicit Arguments.
Section Ctx.
Context {AC : AllocCeiling}.
  Variables (L : Layout) (MI : MallocIface SEGS L) (ST : StaticsIface SEGS L) (DEL_STACK : Z).
  Variables (fx : FPState) (A0 : AS MI) (s : LibIface.SX ST) (R0 : bvmap 5 word) (M0 : mem) (model0 : Model).
  Variables (sp ret st1 st2 : Z) (c1 c2 : stateC) (K : TSet).
  #[local] Abbreviation cfg fx R pc M model := (mkCfg (@mkst fx R (Z_to_bv 64 pc) M (seg_rom SEGS)) model).

  Record smctx : Prop := SMCTX {
    sm_DEL_STACK_nn : 0 <= DEL_STACK;
    sm_DEL : delete_rule_stmt SEGS L MI DEL_STACK;
    sm_MVA1 : mva_stmt SEGS L MI ST DEL_STACK MVA1E 24 Z (nval24 SEGS);
    sm_MVA3 : mva_stmt SEGS L MI ST DEL_STACK MVA3E 24 Z (nval24 SEGS);
    sm_NTI : nt_inl_stmt L MI DEL_STACK;
    sm_HLdel : ly_delete L = DELETE;
    sm_HLimg_lo : forall a, in_ranges (ly_img L) a -> a < alloc_ceiling;
    sm_HLrw_img : forall a, in_ranges (ly_rw L) a -> in_ranges (ly_img L) a;
    sm_HLrelro_img : forall a, in_ranges (ly_relro L) a -> in_ranges (ly_img L) a;
    sm_HLrw_relro : forall a, in_ranges (ly_rw L) a -> ~ in_ranges (ly_relro L) a;
    sm_HLerr_rw : forall a, errno_win L a -> in_ranges (ly_rw L) a;
    sm_CB : callB MI ST A0 s R0 M0 model0 sp ret (STATE_MVA_STACK DEL_STACK);
    sm_H10 : getr R0 10%bv = Z_to_bv 64 st1;
    sm_H11 : getr R0 11%bv = Z_to_bv 64 st2;
    sm_SR1 : state_rep MI A0 M0 st1 c1;
    sm_SR2 : state_rep MI A0 M0 st2 c2;
    sm_AS1 : above_sp MI A0 sp st1 240;
    sm_AS2 : above_sp MI A0 sp st2 240;
    sm_AP : apart st1 240 st2 240;
    sm_DJ : forall b, In b (map fst (state_blocks c1)) -> ~ In b (map fst (state_blocks c2));
    sm_CONT : forall (fx' : FPState) A' R' M' model',
      retB MI ST A' s R0 R' M' model0 model' -> @fp_csr fx' = @fp_csr fx ->
      getr R' 10%bv = Z_to_bv 64 st1 ->
      state_rep MI A' M' st1 (state_moved c1 c2) ->
      state_rep MI A' M' st2 (state_emptied c2) ->
      lapply (live MI A0) (map (fun b => LDel (fst b)) (state_blocks c1)) (live MI A') ->
      eff MI A0 A' M0 M' (sp - STATE_MVA_STACK DEL_STACK, sp) (fun a => state_foot st1 c1 a \/ state_foot st2 c2 a) ->
      srealizes SEGS (cfg fx' R' ret M' model') K
  }.
End Ctx.
Unset Implicit Arguments.

Ltac smctx_pose C :=
  pose proof (sm_DEL_STACK_nn C) as DEL_STACK_nn;
  pose proof (sm_DEL C) as DEL;
  pose proof (sm_MVA1 C) as MVA1;
  pose proof (sm_MVA3 C) as MVA3;
  pose proof (sm_NTI C) as NTI;
  pose proof (sm_HLdel C) as HLdel;
  pose proof (sm_HLimg_lo C) as HLimg_lo;
  pose proof (sm_HLrw_img C) as HLrw_img;
  pose proof (sm_HLrelro_img C) as HLrelro_img;
  pose proof (sm_HLrw_relro C) as HLrw_relro;
  pose proof (sm_HLerr_rw C) as HLerr_rw;
  pose proof (sm_CB C) as CB;
  pose proof (sm_H10 C) as H10;
  pose proof (sm_H11 C) as H11;
  pose proof (sm_SR1 C) as SR1;
  pose proof (sm_SR2 C) as SR2;
  pose proof (sm_AS1 C) as AS1;
  pose proof (sm_AS2 C) as AS2;
  pose proof (sm_AP C) as AP;
  pose proof (sm_DJ C) as DJ;
  pose proof (sm_CONT C) as CONT;
  pose proof (cb_ainv _ _ _ _ _ _ _ _ _ _ _ _ (sm_CB C)) as AI0;
  pose proof (cb_mstd _ _ _ _ _ _ _ _ _ _ _ _ (sm_CB C)) as MS0;
  pose proof (cb_regs _ _ _ _ _ _ _ _ _ _ _ _ (sm_CB C)) as CR0;
  pose proof (cb_roc _ _ _ _ _ _ _ _ _ _ _ _ (sm_CB C)) as ROC0.

