  #[local] Abbreviation sx_inv_via_eff' := (sx_inv_via_eff L MI ST (sm_HLimg_lo C) (sm_HLrw_img C) (sm_HLrelro_img C) (sm_HLrw_relro C) (sm_HLerr_rw C)).
